from heapq import heappop, heappush

def dijkstra(graph, start):
    distance = {}
    for vertex in graph:
        distance[vertex] = float("inf")
    distance[start] = 0
    heap = [(0, start)]
    while heap:
        current, vertex = heappop(heap)
        if current != distance[vertex]:
            continue
        for neighbor, weight in graph[vertex]:
            candidate = current + weight
            if candidate < distance[neighbor]:
                distance[neighbor] = candidate
                heappush(heap, (candidate, neighbor))
    return distance

graph = {
    "A": [("B", 4), ("C", 1)],
    "B": [("D", 1)],
    "C": [("B", 2), ("D", 5)],
    "D": [],
    "E": [],
}
distance = dijkstra(graph, "A")
for vertex in graph:
    print(vertex, distance[vertex])

from heapq import heappop, heappush

def dijkstra_core(graph, start):
    distance = {v: float("inf") for v in graph}
    parent = {v: None for v in graph}
    stale = 0
    if not graph:
        return distance, parent, stale
    distance[start] = 0
    heap = [(0, start)]
    while heap:
        current, vertex = heappop(heap)
        if current != distance[vertex]:
            stale = stale + 1
            continue
        for neighbor, weight in graph[vertex]:
            candidate = current + weight
            if candidate < distance[neighbor]:
                distance[neighbor] = candidate
                parent[neighbor] = vertex
                heappush(heap, (candidate, neighbor))
    return distance, parent, stale

def dijkstra_distances(graph, start):
    return dijkstra_core(graph, start)[0]

print(dijkstra_distances({'A': [('B', 4), ('C', 1)], 'B': [('D', 1)], 'C': [('B', 2), ('D', 5)], 'D': [], 'E': []}, 'A'))
print(dijkstra_distances({'A': [('B', 0)], 'B': [('A', 0)], 'C': []}, 'A'))
print(dijkstra_distances({}, None))

