def cheapest_path(graph, start, goal):
    if not graph:
        return None
    distance, parent, _ = dijkstra_core(graph, start)
    if distance[goal] == float("inf"):
        return None
    path = []
    vertex = goal
    while vertex is not None:
        path.append(vertex)
        vertex = parent[vertex]
    return distance[goal], path[::-1]

